INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(100, 0, 1, 0, 0, 0, 'Dun Morogh', 'Dun Morogh is the snowbound heart of Khaz Modan, a high country of frozen lakes, pine forests and wind-scoured ridges, walled in by mountains and reached only through a few passes kept by dwarven mountaineers. It is the homeland of the Ironforge dwarves, whose great city is carved into the mountain at its heart, and of the gnomes, whose city of Gnomeregan lies beneath the western hills. The Frostmane ice trolls once ruled these snows, until dwarven armies broke their empire and drove them into the hills, and they trouble the dwarves still. Now worse troubles have come. Troggs have poured out of the deep places, seizing the Coldridge tunnel and the Gol''Bolar Quarry, and Gnomeregan itself was lost, its halls poisoned and its people scattered across the land. With much of King Magni''s army fighting far away beside the Alliance, mountaineers, Senate envoys and any stout-hearted volunteers must hold the line.', 'warcraft.wiki.gg/wiki/Dun_Morogh_(Classic) (snowy region, Khaz Modan mountains on all sides, passes guarded by dwarven troops, home of gnomes and dwarves); warcraft.wiki.gg/wiki/Frostmane_tribe (once ruled Dun Morogh, empire fell to dwarven armies, retreat to the hills); warcraft.wiki.gg/wiki/Gnomeregan (western Dun Morogh); quest 170 description and reward text; quest 433 description; quest 2160 reward text; quest 3361 description (gnomes scattered all over Dun Morogh); quest 314 description (King Magni''s army off fighting with the Alliance)'),
(101, 1, 1, 1, 0, 0, 'Coldridge Valley', 'Coldridge Valley is a sheltered vale in the southwestern corner of Dun Morogh, where young dwarves and gnomes take their first steps as defenders of Khaz Modan. Wolves and crag boars roam its snowfields, and the hunter Talin Keeneye keeps a camp beside the frozen lake. The valley is far from peaceful. Frostmane trolls hold a cave at its southern end, and the Senate envoy Grelin Whitebeard camps in the valley to weigh the threat they pose. Rockjaw troggs have spread across the southeastern hills, even overrunning a dwarven camp to the west. The gnome Felix Whindlebolt, fleeing the ruin of Gnomeregan, found refuge here only to have the trolls carry off his belongings.', 'warcraft.wiki.gg/wiki/Coldridge_Valley (southwestern corner, dwarf and gnome start before Cataclysm); quest 233 description (Talin''s camp by the frozen lake); quest 170 description; quests 182, 218 (description and reward text); quest 3361 description; DB spawns in area 132: Ragged wolves, Small Crag Boar, Rockjaw Trogg, Frostmane Troll Whelp, Grik''nir 808; quest 182 description (Grelin sent to investigate the troll threat)'),
(102, 1, 1, 2, 1, 0, 'Anvilmar', 'Anvilmar is a dwarven settlement dug into the mountainside at the northern edge of Coldridge Valley, the first place of any size a newcomer to the valley will find. Around its great forge, trainers of many callings instruct new recruits, and merchants sell arms, armor and warm clothing. Durnan Furcutter swears there is nothing like a cup of scalding mornbrew on a chilly Dun Morogh day, though Nori Pridedrift, who brings it up from Grelin Whitebeard''s camp, fears no cup will reach him before it runs cold. The gnome Felix Whindlebolt has sheltered here since fleeing Gnomeregan, though he grumbles that the place holds as many nasty creatures as his old home did before the accident.', 'warcraft.wiki.gg/wiki/Anvilmar (northern Coldridge Valley, first settlement of significance, large forge, class trainers); quest 3364 description (a settlement dug into the mountain); quest 3365; creature_text 836; quest 3361 completion text; DB spawns: trainers 912, 926, 944, 460, 837, 895, 916; vendors 829, 836, 1104 in Coldridge Valley; WMOAreaTable.dbc: Anvilmar WMO (root 752) maps to area 0, and no map tile carries area 77, so the server never reports Anvilmar'),
(103, 1, 1, 3, 0, 0, 'Coldridge Pass', 'Coldridge Pass is the tunnel linking Coldridge Valley with the rest of Dun Morogh, and the troggs have claimed it. Rockjaw raiders lurk along its length and fall on anyone passing through, and Mountaineer Thalos keeps watch at the valley end, asking travelers with no pressing business to stay in Anvilmar until the way is safer. Since the troggs overran the pass, scarcely any word from Anvilmar has reached Kharanos. Near the tunnel mouth the gnome Hands Springsprocket waits with a crate of supplies for the inn at Kharanos, unable to cross until a mountaineer escort comes through, and glad to hand it to any hardy traveler bound that way.', 'quest 282 description and completion text; quest 420 description; quest 2160 description and reward text; DB spawns in area 800: Rockjaw Raider 1718, Mountaineer Thalos 1965, Hands Springsprocket 6782, Coldridge Mountaineers'),
(104, 1, 1, 4, 0, 0, 'Kharanos', 'Kharanos is the bustling heart of Dun Morogh, a dwarven town nestled among the peaks on the road north to Ironforge. It has a large forge and a gnomish workshop, and its pride is the Thunderbrew Distillery, where Innkeeper Belm invites travelers to fill a tankard and pull up a chair. Mountaineers guard its roads, and recruits who come up through the Coldridge tunnel continue their training here. Kharanos is also where Senir Whitebeard, envoy of the Senate, keeps an eye on the Frostmane trolls, and where the gnomes Ozzie Togglevolt and Razzle Sprysprocket labor over a machine they believe can cure the leper gnomes of Gnomeregan.', 'warcraft.wiki.gg/wiki/Kharanos (bustling town among the peaks, large forge, gnomish workshop, Thunderbrew Distillery, recruits from Anvilmar train there); npc_text 823 (Innkeeper Belm); quest 291 description (road north to Ironforge); warcraft.wiki.gg/wiki/Senir_Whitebeard (special envoy of the Senate); quest 412 description; DB spawns in area 131: Ironforge Mountaineers, Senir 1252, Ozzie 1268, Razzle 1269, Captured Leper Gnome 5568, gameobject 26449 Recombobulator'),
(105, 1, 1, 5, 0, 0, 'Thunderbrew Distillery', 'The Thunderbrew Distillery is the most famous building in Kharanos, tavern, inn and brewery in one, and the home of Thunder Ale. Ragnar Thunderbrew presides over the taps. Down in the cellar, Jarven Thunderbrew guards the barrels under strict orders not to touch a drop, though he admits a taste of Thunder Ale would sharpen his wits. The Thunderbrews guard their recipes jealously, and with reason. Dark Iron dwarves have already stolen the family''s recipe for Thunderbrew Lager, and the rival Barleybrews of Brewnall Village would dearly love to see their own Scalder served to Thunderbrew patrons in place of the house ale.', 'warcraft.wiki.gg/wiki/Thunderbrew_Distillery (famous dwarven tavern in Kharanos with inn and trainers); quest 308 completion and reward text; quest 310 description; quests 4126, 4128; DB: Ragnar Thunderbrew 1267 and Jarven Thunderbrew 1373 in Kharanos; gameobjects 269/270 Thunder Ale barrels; WMOAreaTable.dbc: Thunderbrew Distillery WMO (root 1970, name set 1) maps to area 2102'),
(106, 1, 1, 6, 0, 0, 'Steelgrill''s Depot', 'Just northeast of Kharanos stands Steelgrill''s Depot, the shop of Beldin Steelgrill, reckoned the best siege engine mechanic there is and notoriously hard on his tools. It is a favorite haunt of veteran siege engine pilots, and Pilot Stonegear and Pilot Bellowfiz trade boasts about their machines while they wait on his repairs. Milli Featherwhistle sells mechanostriders from the yard and Binjy Featherwhistle teaches gnomes to ride them, and Loslor Rudge keeps the engineers supplied.', 'quest 400 description and reward text; creature_text 1377, 1378; quests 313, 317; npc_text 4253 (Loslor Rudge); DB spawns in area 189: Milli 7955 and Binjy Featherwhistle 7954 (mechanostriders), Gnomeregan Trainee 39349, Disassembled Mechano-Tank 39263, Captain Tread Sparknozzle 39675; quest 25285 description (mechano-tanks readied for the assault)'),
(107, 1, 1, 7, 0, 0, 'The Grizzled Den', 'The Grizzled Den lies in the snowy hills west of Kharanos, the lair of a band of wendigo. These shaggy brutes make the surrounding slopes dangerous: a courier hauling a crate of ammunition for the gunsmith Hegnar Rumbleshot was chased off near the den and fled without his cargo. Their thick manes are prized all the same, and Pilot Stonegear wants a heap of them as a rug for the deck of his siege engine. South of the den, snowfields teem with crag boars and bears, hunted for meat and fur by those who supply the depot.', 'quest 313 description (Grizzled Den, west of Kharanos); quest 5541 description; quest 317 description (snow fields south of the Grizzled Den); DB spawns in area 136: Wendigo 1135, Young Wendigo 1134, Crag Boar, Young Black Bear; gameobject 176785 Ammo Crate'),
(108, 1, 1, 8, 0, 0, 'Chill Breeze Valley', 'Chill Breeze Valley is a stretch of wild country west of Kharanos, roamed by wendigo and big crag boars. Here Tundra MacGrann keeps a lonely camp and hunts deer in spite of a bad leg. He had salted away a month of dried meat for the cold season in a thorium locker, safe from bears, but while he was off hunting, the great wendigo Old Icebeard carried the whole locker away to its cave. Too slow on his bum leg to slip in and out of the lair, MacGrann faces a hungry winter unless someone retrieves his stash. A wendigo known as Edan the Howler also prowls the valley.', 'quest 312 description and reward text; DB spawns in area 801: Old Icebeard 1271, Tundra MacGrann 1266, gameobject 272 MacGrann''s Meat Locker, Wendigo, Large Crag Boar, Edan the Howler 1137; creature_loot_template: Old Icebeard and Edan drop Wendigo Mane; warcraft.wiki.gg/wiki/Old_Icebeard (elite wendigo, Classic location a cave in Chill Breeze Valley); warcraft.wiki.gg/wiki/Edan_the_Howler (rare wendigo)'),
(109, 1, 1, 9, 0, 0, 'Brewnall Village', 'Brewnall Village stands on the west bank of Iceflow Lake, west of Kharanos, home of the Barleybrew family. Rejold Barleybrew is on a quest to brew the perfect stout and will try any ingredient, even the shimmerweed the Frostmane trolls grow for their rituals. Some of his brews taste good, some bad, and some, like the fiery Evershine, would lay all but the stoutest dwarf flat. Marleth Barleybrew nurses a rivalry with the Thunderbrews of Kharanos. Bears, snow leopards and old crag boars wander close to the village, and the brewers would gladly see them thinned so they can get on with their crafting and brewing.', 'quest 287 description (Brewnall Village on the west bank of Iceflow Lake); quest 318 description (west of Kharanos; Evershine); quests 315, 319, 310; warcraft.wiki.gg/wiki/Brewnall_Village (home of the Barleybrews, protect the village from wild animals); DB spawns in area 137: Rejold 1374, Marleth 1375, Keeg Gibn 1697'),
(110, 1, 1, 10, 0, 0, 'Iceflow Lake', 'Iceflow Lake is the frozen lake of western Dun Morogh, reached by following the frozen river west from the bridge on the road north of Kharanos. Brewnall Village stands on its western bank, and Frostmane Hold lies in the hills beyond. Along its shore the Ganters keep a fishing camp, with Paxton Ganter teaching the trade and Gretta Ganter selling fishing supplies. Winter wolves hunt the snows around the lake, some of them gaunt and starving, and a great wolf called Timber is sometimes seen among them.', 'quest 287 description (directions to Iceflow Lake); DB spawns in area 211: Paxton Ganter 1700 (Fishing Trainer), Gretta Ganter 8508 (Fishing Supplies), Winter Wolf 1131, Starving Winter Wolf 1133, Timber 1132'),
(111, 1, 1, 11, 0, 0, 'Frostmane Hold', 'Frostmane Hold is the stronghold of the Frostmane ice trolls, a cave in the hills southwest of Brewnall Village. Their empire once spanned Dun Morogh, until the dwarves broke it and drove the survivors into the hills, a shameful blow to so warlike a people. Headhunters, hideskinners and shadowcasters crowd the Hold in such numbers that Senir Whitebeard, who found it, did not dare go inside. Great Father Arctikus, patriarch of the tribe, walks the snows around it, and in the foothills just to the south stands the hut of Vejrek, said to be the toughest troll in these parts.', 'quest 287 description; warcraft.wiki.gg/wiki/Frostmane_tribe (empire fell to dwarven armies, shameful blow to their warlike nature, Frostmane Hold their capital, Arctikus patriarch); quest 1678 description (Vejrek''s hut south of Frostmane Hold); DB spawns in area 135: Frostmane Headhunter, Hideskinner, Shadowcaster, Snowstrider, Great Father Arctikus 1260, Vejrek 6113'),
(112, 1, 1, 12, 0, 0, 'Shimmer Ridge', 'Shimmer Ridge rises in the hills east of Brewnall Village, where the Frostmane trolls grow shimmerweed, a plant they use in their strange tribal rituals. Frostmane seers tend the crop and store it in baskets, with snowstriders and headhunters standing guard, and they have no patience for outsiders after their harvest. The dwarves have found little use for the weed, but its unique taste has caught the fancy of Rejold Barleybrew of Brewnall Village, who is eager to try it in his brews.', 'quest 315 description; warcraft.wiki.gg/wiki/Frostmane_tribe (grew shimmerweed on Shimmer Ridge for rituals); creature_text 1397; DB spawns in area 802: Frostmane Seer 1397, gameobject 276 Shimmerweed Basket, Frostmane Snowstrider, Headhunter'),
(113, 1, 1, 13, 0, 0, 'Gnomeregan', 'In the western hills of Dun Morogh lies the surface entrance to Gnomeregan, once the capital of the gnomes. When troggs invaded from below, the gnomes fought back with a radiation purge that went horribly wrong, poisoning their own city and killing or twisting a great many of its people. The survivors scattered across Dun Morogh or fled to Ironforge. The land before the gates now belongs to leper gnomes, their minds clouded by sickness, some so addled that they take any stranger for a trogg. Irradiated trogg looters prowl near the entrance, and a few evacuees still try to slip away.', 'warcraft.wiki.gg/wiki/Gnomeregan (trogg invasion, radiation plan, heavy losses, refugees to Ironforge, entrance in western Dun Morogh); quest 3361 description; quest 412 description; creature_text 6221 (Addled Leper), 7843 (Gnomeregan Evacuee), 6209; DB spawns in area 133: Leper Gnome 1211, Addled Leper 6221, Gnomeregan Evacuee 7843; Caverndeep Looter/Invader/Pillager and Irradiated Invader nearby'),
(114, 1, 1, 14, 0, 0, 'Amberstill Ranch', 'Amberstill Ranch lies on the eastern road toward Loch Modan, where the Amberstill family breeds the sturdy rams that carry the dwarves of Ironforge. Veron Amberstill will hand the reins of a ram only to a proven ally of Ironforge, and Ultham Ironhorn teaches riders to handle them. Yarlyn Amberstill spends the days chasing a rabbit called Fluffy, who wants no part of a bath. The herd has a deadly enemy in Vagash, a wendigo who lurks on the slopes above the ranch and picks off rams in the night, and with most of King Magni''s army away with the Alliance, Rudra Amberstill has no soldiers to call on.', 'warcraft.wiki.gg/wiki/Amberstill_Ranch (north of Gol''Bolar on the road to Loch Modan, rams, Vagash a Wendigo); npc_text 5856 (Veron); creature_text 1263 (Yarlyn and Fluffy); quest 314 description and reward text; DB spawns in area 803: Veron 1261, Rudra 1265, Yarlyn 1263, Fluffy 1352, Ultham Ironhorn 4772, Vagash 1388'),
(115, 1, 1, 15, 0, 0, 'Gol''Bolar Quarry', 'Gol''Bolar Quarry is a great dig site in southeastern Dun Morogh, worked by Ironforge''s miners until they dug too deep. Troggs poured out of the earth, wrecked the equipment and drove the miners from their own pit, and now Rockjaw skullthumpers and bonesnappers swarm the workings while the dwarves hold a camp at the rim. Foreman Stonebrow of the Miners'' League watches his blasting powder go up in smoke and rages for revenge, and Senator Mehr Stonehallow has come in person to see the quarry cleared and the miners back at work. In the shadier corners of Ironforge, some whisper that the king is stripping the quarry of ore and gems.', 'warcraft.wiki.gg/wiki/Gol%27Bolar_Quarry (dig site in southeastern Dun Morogh, troggs took over, Miners'' League); quest 432 description; quest 433 description and reward text; quests 2238, 2239 (Hidden Circle claims about the King strip mining the quarry); DB spawns in area 134: Rockjaw Skullthumper 1115, Bonesnapper 1117, Foreman Stonebrow 1254, Senator Mehr Stonehallow 1977, Dun Morogh Mountaineers'),
(116, 1, 1, 16, 0, 0, 'Helm''s Bed Lake', 'Helm''s Bed Lake is a small frozen lake in southeastern Dun Morogh, and its shores are no place to linger. Rockjaw troggs, from ambushers to backbreakers, crowd its banks, and scarred crag boars roam the surrounding hills. South of the lake lies something the dwarves like even less. Dark Iron dwarves have bunkered down in an old compound there, and two dwarves who crept close enough to spy on them saw their leader giving orders to his men before more of the Dark Irons caught them by surprise.', 'warcraft.wiki.gg/wiki/Helm%27s_Bed_Lake (small lake in southeastern Dun Morogh, Dark Irons in an abandoned building to the south); quest 1783 description; DB spawns in area 212: Rockjaw Ambusher 1116, Backbreaker 1118, Bonesnapper 1117, Skullthumper 1115, Scarred Crag Boar 1689'),
(117, 1, 1, 17, 0, 0, 'Ironband''s Compound', 'South of Helm''s Bed Lake stands the compound of Sturgy Ironband, a master blacksmith who once taught his craft to students here. One day a student brought him a load of strange ore, which Ironband called umbral ore and was eager to work. Soon after it arrived, a band of Dark Iron dwarves attacked the compound and killed everyone inside. The Dark Irons hold it still, their spies and their captain, Beld, falling on any who come near. Narm Faulk, a dwarf of the Light, fell nearby while spying on them, having stayed behind so that his companion could escape and fetch help.', 'quest 1681 description and reward text; quests 1783, 1784 (Narm Faulk); creature_template 6124 Captain Beld <Dark Iron Captain>; creature_text 6123, 6124; DB spawns in area 716: Dark Iron Spy 6123 x12, Captain Beld 6124, Narm Faulk 6177, gameobject 85562 Ironband''s Strongbox; warcraft.wiki.gg/wiki/Ironband%27s_Compound'),
(118, 1, 1, 18, 0, 0, 'North Gate Outpost', 'North Gate Outpost is one of the two dwarven guard towers watching the passes from Dun Morogh into Loch Modan, held by mountaineers. In the hills nearby, Pilot Hammerfoot of the Siege Brigade stands guard over the engines he and his friend Mori Hildelve drove here in search of a rare ore needed for high-grade blastpowder. Hildelve wrecked his engine on a steep slope and went on searching alone, on foot. That was days ago, and he has not come back. Since then Hammerfoot has heard beastly growls in the hills at night, and he is starting to worry.', 'quest 413 description (one of two towers on the border to Loch Modan); quest 419 description and reward text; quest 417 description and reward text; DB spawns in area 808: Pilot Hammerfoot 1960, Mangeclaw 1961, gameobject 2059 A Dwarven Corpse, Dun Morogh Mountaineers'),
(119, 1, 1, 19, 0, 0, 'South Gate Outpost', 'South Gate Outpost is the southern of the two guard towers on Dun Morogh''s border with Loch Modan, where mountaineers watch over the tunnel that leads southeast toward Thelsamar. Its best known sentry is Mountaineer Wellart Barleybrew, brother of the brewer Rejold. He is no brewer like the rest of his family, but he loves his drink, and he grumbles that he has not had a good fight in days and his barrel of ale is nearly dry.', 'quest 413 description, completion and reward text; quest 414 description (southeast through the tunnel to Thelsamar); DB spawns in area 806: Mountaineer Barleybrew 1959, Dun Morogh Mountaineers'),
(120, 2, 1, 1, 1, 0, 'Grelin Whitebeard', 'Grelin Whitebeard and his brother Senir were sent by the Senate of Ironforge to weigh the threat the trolls pose to Dun Morogh, and Grelin made his camp in Coldridge Valley. The Senate has its hands full with the troggs and wants no further annoyances. From what Grelin has seen, the Frostmane here are poorly placed, mostly confined to the valley''s southern cave, and he judges that the army will not be needed when a few strong arms will serve. He has the authority to pay those who lend them, and he is always glad of mail, since word from Ironforge comes to his camp but rarely.', 'quest 182 description and reward text; quest 218; quest 282 description; quest 234 reward text; warcraft.wiki.gg/wiki/Frostmane_tribe (the Senate sent Grelin and Senir Whitebeard)'),
(121, 2, 1, 2, 1, 0, 'Senir Whitebeard', 'Senir Whitebeard, Grelin''s brother and a special envoy of the Senate, works out of Kharanos, sent to look into the threat the Frostmane trolls pose to Dun Morogh. He is a sociable soul who would sooner share a drink than tramp through the snow, there being little else to do in the cold, and he freely admits he has fallen behind on his report, blaming the bloody cold. It was Senir who found where the trolls are holed up, at Frostmane Hold, though the sheer numbers he saw there kept him from going in.', 'warcraft.wiki.gg/wiki/Senir_Whitebeard (special envoy of the Senate of Ironforge, Kharanos); quest 420 completion and reward text; quest 287 description and reward text; quest 291 description'),
(122, 2, 1, 3, 1, 0, 'Senator Mehr Stonehallow', 'Senator Mehr Stonehallow sits in the Senate of Ironforge and belongs to the Explorers'' League, yet he has left the city to take charge of the trogg problem at the Gol''Bolar Quarry himself. He has no illusions about the troggs. As the miners dug deep, the creatures poured out, smashed the equipment and drove everyone away, and he sees nothing to do but exterminate them. His plan is plain: clear the pit, bring in mountaineers to hold it, rebuild and put the miners back to work, the first step of many against an infestation gripping the dwarven lands.', 'quest 433 description, completion and reward text; DB spawn: Senator Mehr Stonehallow 1977 at Gol''Bolar Quarry'),
(123, 2, 1, 4, 1, 0, 'Rejold and Marleth Barleybrew', 'The Barleybrews of Brewnall Village are a family of brewers, and Rejold Barleybrew is their restless genius, sure that brewing is in his blood and the perfect stout within his reach. He will experiment with anything, from troll-grown shimmerweed to the fiery Evershine that one siege pilot throws into his engine''s furnace for a burst of power. Marleth Barleybrew grudgingly admits the Thunderbrews make good drinks, but means to teach them theirs is not the only decent brew, even if it takes a barrel of Barleybrew Scalder smuggled into the Thunderbrew cellar. Rejold''s brother Wellart, no brewer at all, serves as a mountaineer on the Loch Modan border.', 'quests 315, 318, 319, 413, 415; quests 310, 311; warcraft.wiki.gg/wiki/Brewnall_Village'),
(124, 2, 1, 5, 1, 0, 'Ragnar Thunderbrew', 'Ragnar Thunderbrew presides over the Thunderbrew Distillery in Kharanos and is fiercely proud of the family recipes, from Thunder Ale to his famous Beer Basted Boar Ribs, whose secret, he swears, is in the malt. Supplies have been harder to come by since his trapper went off to join the king''s army at the Alliance front. Ragnar has a temper. When Dark Iron dwarves led by Hurley Blackbreath stole the family recipe for Thunderbrew Lager, he swore they were in for it, and he will reward any champion willing to turn Blackrock Depths upside down to bring it back.', 'quest 384 description and reward text; quest 4126 description; quest 4128 reward text; warcraft.wiki.gg/wiki/Thunderbrew_Distillery'),
(125, 2, 1, 6, 1, 0, 'Ozzie Togglevolt and Razzle Sprysprocket', 'Ozzie Togglevolt and Razzle Sprysprocket are gnomish inventors working out of Kharanos with one goal: to undo what Gnomeregan''s radiation did to their people. Their grand project is the Recombobulator, a machine meant to reverse the leper affliction, which they test on a captured leper gnome with mixed results and endless adjustments. Ozzie is also working on a cure made from the green glow of irradiated troggs, though by his own admission it might just turn out to be a very powerful rum. He was standing beside Gnoarn on the day a radiation bolt took all of Gnoarn''s hair.', 'quest 412 description and reward text; quests 2926, 2927, 2962; creature_text 1269, 5568; warcraft.wiki.gg/wiki/Ozzie_Togglevolt (working on a cure for leper gnomes with Razzle)'),
(126, 2, 1, 7, 1, 0, 'Pilot Stonegear and Pilot Bellowfiz', 'Two veteran siege engine pilots pass the time at Steelgrill''s Depot, waiting on Beldin Steelgrill''s repairs and arguing about everything. Pilot Stonegear drives ''Trollplow'', a heavily armored engine whose battle scars he wears with pride, and he scoffs at any design that sheds armor to save weight. Pilot Bellowfiz would rather race the circuit than fight in the arena, and swears a splash of Evershine in the furnace of his ''Jetsteam'' has carried him out of more than one tight spot. Stonegear wants wendigo manes for a rug, while Bellowfiz is stocking up for a long mission for the Siege Brigade.', 'creature_text 1377, 1378; quest 313 description; quests 317, 318 description; quest 400 reward text (repairs on Stonegear''s siege engine)'),
(127, 2, 1, 8, 1, 0, 'Felix Whindlebolt', 'Felix Whindlebolt is one of the gnomes scattered across Dun Morogh when Gnomeregan was lost. As he tells it, the gnomes drove the troggs out of their city, and then it all went horribly wrong, leaving their home completely irradiated. Felix fled in such haste that he lost all his belongings and tools, and the Frostmane trolls carried off his chest, his box and his bucket of bolts to their camps southwest of Anvilmar. No adventurer, he waits in Anvilmar, convinced the place is no fit home for the likes of him, and gloomily observes that things are not looking good for Felix.', 'quest 3361 description and completion text; npc_text 15139'),
(128, 2, 1, 9, 0, 0, 'Grik''nir the Cold', 'Grik''nir the Cold leads the Frostmane trolls who hold the cave at the southern end of Coldridge Valley, a band Grelin Whitebeard thought too poorly placed to need the army. A big brute with odd markings on his skin and face, he keeps to the cave among the troll whelps and novices of his band, far from Frostmane Hold, the tribe''s stronghold in the western hills.', 'quest 182 reward text; quest 218 description; warcraft.wiki.gg/wiki/Grik%27nir_the_Cold (Frostmane Hovel at the southern end of Coldridge Valley); DB spawns in area 132: Grik''nir 808, Frostmane Troll Whelp 706, Frostmane Novice 946; warcraft.wiki.gg/wiki/Frostmane_tribe (Grik''nir as a secondary leader); quest 182 description (trolls mostly in the southern cave, army not needed)'),
(129, 2, 1, 10, 0, 0, 'Great Father Arctikus', 'Great Father Arctikus is the patriarch of the Frostmane tribe, the ice trolls who ruled Dun Morogh before the dwarves broke their empire. He carries the Frostmane Scepter and wears the Royal Frostmane Girdle as marks of his station, and he walks the snows around Frostmane Hold, the tribe''s stronghold in the western hills. Any stranger who intrudes there is told plainly that defiling Frostmane Hold will cost a life. To the dwarves he is a reminder that the Frostmane, though driven into the hills long ago, still follow a leader of their own.', 'warcraft.wiki.gg/wiki/Frostmane_tribe (former patriarch and great leader; Frostmane Scepter, Royal Frostmane Girdle); creature_text 1260; creature_loot_template 1260 (items 2546, 3223); DB spawns: Great Father Arctikus at Frostmane Hold (area 135) and nearby'),
(130, 3, 1, 1, 1, 0, 'The Whitebeard Reports', 'With its hands full of troggs, the Senate of Ironforge wants no further annoyances, so it sent the brothers Grelin and Senir Whitebeard to weigh the threat the Frostmane trolls pose to Dun Morogh. Senir works from Kharanos, while Grelin camps in Coldridge Valley. From what Grelin has seen, the trolls of the valley are poorly placed, mostly confined to the southern cave, and he judges the army unnecessary: a few strong arms should be more than enough. He has the authority to pay for them, and once the trolls are dealt with he means to write up his findings for the Senate.', 'quests 182, 218, 282, 420, 287, 291 (descriptions, completion and reward texts); warcraft.wiki.gg/wiki/Frostmane_tribe (Senate sent the Whitebeards)'),
(131, 3, 1, 2, 1, 0, 'The Trogg Menace', 'Troggs have burst out of the deep places of Khaz Modan, and all of Dun Morogh feels it. In Coldridge Valley, Balir Frosthammer reports them across the southeastern hills and by the frozen lake, and only nights ago they overran a dwarven camp to the west. They hold the tunnel to Kharanos so firmly that supplies and news have all but stopped, and the gnome Hands Springsprocket must ask passing travelers to carry a crate through to the inn. At the Gol''Bolar Quarry they poured out of the diggings, wrecked the equipment and drove off the miners. Foreman Stonebrow rages as his powder barrels go up one by one, while Senator Mehr Stonehallow, who has taken this part of the infestation upon himself, sees nothing to do but exterminate the troggs, rebuild and put the miners back to work.', 'quest 170 description and reward text; quest 2160 description and reward text; quests 282, 420 (tunnel infested); quest 432 description; quest 433 description and reward text'),
(132, 3, 1, 3, 1, 0, 'Barleybrew and Thunderbrew', 'Brewing is serious business in Dun Morogh. In Brewnall Village, Marleth Barleybrew admits the Thunderbrews of Kharanos make good drinks, but means to teach them that theirs is not the only decent brew. The plan is to slip a barrel of Barleybrew Scalder into the Thunderbrew Distillery''s cellar in place of their Thunder Ale, and see how the patrons like it. The cellar guard, Jarven Thunderbrew, is under orders not to touch the ale, which is exactly why a mug of it makes such a fine distraction. Rejold Barleybrew, meanwhile, is on a quest for the perfect stout. He wants shimmerweed, which the Frostmane trolls grow on the ridge to the east for their rituals, sure that its unique taste belongs in his next batch.', 'quests 308, 310, 311 (descriptions, completion and reward texts); quests 315, 415, 413, 414 (descriptions and reward texts)'),
(133, 3, 1, 4, 1, 0, 'Pilots of the Siege Brigade', 'Steelgrill''s Depot draws the pilots of the Ironforge Siege Brigade, and their errands send helpers all over Dun Morogh. It begins with a crate of tools for Beldin Steelgrill, who broke his last fang-ratchet in the middle of repairs on Pilot Stonegear''s engine. Stonegear wants wendigo manes from the Grizzled Den to carpet ''Trollplow'', while Pilot Bellowfiz stocks ''Jetsteam'' with boar meat and bear fur for a month-long mission, plus a cask of Rejold Barleybrew''s Evershine to burn in its furnace. Far to the east, Pilot Hammerfoot guards the engines while his friend Mori Hildelve searches the hills on foot for a rare ore for blastpowder. Days have passed with no word, and something growls in those hills at night.', 'quest 400 description and reward text; quest 313; quests 317, 318, 319, 320; quests 419, 417 (descriptions and reward texts)'),
(134, 3, 1, 5, 1, 0, 'The Recombobulator', 'Gnomeregan''s fall cost the gnomes more than a home. The attempt to purge the troggs not only failed but turned much of their own people into mindless, hostile leper gnomes. In Kharanos, Ozzie Togglevolt and Razzle Sprysprocket mean to set it right. Their Recombobulator needs Restabilization Cogs and Gyromechanic Gears, salvaged from the very lepers who roam outside the city gates, and Razzle tinkers endlessly with a captured leper who seems less than thrilled. Ozzie pursues a second cure, drawn from the green glow of irradiated troggs, though it may yet turn out to be a very powerful rum. Gnoarn of Ironforge, who lost a magnificent head of hair to a radiation bolt and has thought of nothing but cleansing Gnomeregan since, sends helpers his way.', 'quest 412 description and reward text; quests 2927, 2926, 2962 (descriptions and reward texts); creature_text 1269, 5568');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(106, 1, 13, 255, 'Of late the depot has grown crowded. Gnomeregan trainees stand in ranks in the yard, and beside Captain Tread Sparknozzle a row of half-assembled mechano-tanks waits to be readied and tested, for the exiles of Gnomeregan are preparing machines and recruits for an assault to take back their city.', 'DB spawns in area 189: Gnomeregan Trainee 39349 (12, in ranks), Disassembled Mechano-Tank 39263, Captain Tread Sparknozzle 39675, all phase 1; quest 25285 description (mechano-tanks readied for the assault); warcraft.wiki.gg/wiki/Operation:_Gnomeregan (patch history: added in patch 3.3.5)'),
(118, 1, 0, 255, 'Hildelve lies in the snow not far from the engines, mauled, frozen and picked clean by mountain scavengers, his Brigadier''s Vest still on him and his journal clutched in his hand. In it he wrote that a huge ice claw bear called Mangeclaw attacked him. He drove the beast off, but it came back to finish him, and his last wish was revenge.', 'quest 419 reward text (the corpse); quest 417 description (journal, Mangeclaw, final wish); DB: gameobject 2059 A Dwarven Corpse in area 808'),
(119, 1, 0, 255, 'A barrel of his brother''s new Shimmer Stout has reached the tower, and one taste put a shine in Wellart''s eyes. He swore he could see in the dark. He liked it so well that he kept on drinking it, and soon wanted a fellow mountaineer, Kadrell, who patrols the road through Thelsamar, to try it as well.', 'quest 413 reward text; quest 414 description'),
(120, 1, 0, 255, 'The trolls answered in the night. A group of them crept into Grelin''s camp and stole his journal, the notes his report depends on, and carried it off to their cave. The one who had it was a big brute with odd markings on his skin and face, and Grelin, fuming, mutters that he knew better than to trust his good-for-nothing apprentice.', 'quest 182 reward text; quest 218 description'),
(120, 2, 0, 255, 'With his notebook back, Grelin declares the troll situation in Coldridge Valley under control and not much cause for worry. He puts the finishing touches on his report for Senir, and he will not leave it to his apprentice: he wants it carried in more reliable hands through the trogg-infested tunnel to Kharanos.', 'quest 218 reward text; quest 282 description'),
(120, 3, 0, 255, 'Grelin''s report leans on the King''s name, though Senir had told him to be sparing with it. When it reaches Kharanos, Senir judges it sure to ruffle some feathers in the Senate, and is not sorry: those feathers, he says, needed ruffling.', 'quest 420 reward text'),
(121, 1, 0, 255, 'When Grelin''s report reaches him, Senir reads it with a grin. He told his brother to be sparing with the King''s name, but Grelin did not listen. It is sure to ruffle some feathers in the Senate, Senir admits, though in his view those were feathers that needed ruffling, and it reminds him that his own report is overdue.', 'quest 420 reward text'),
(121, 2, 0, 255, 'Once the Hold has been scouted, Senir scribbles out his report at last, laughing at something in it, and sends it to Senator Barin Redstone, a sour sort who waits in the chamber in Ironforge where King Magni holds court. He asks only that no one mention how much help he had: the Senate must not think he is idle out here.', 'quest 287 reward text; quest 291 description'),
(128, 1, 0, 255, 'It was Grik''nir and a group of his trolls who crept into Grelin''s camp in the night and made off with the dwarf''s journal, the notes his report to the Senate depends on. Grik''nir keeps it with him in the cave, and Grelin wants it back.', 'quest 182 reward text; quest 218 description and objective'),
(130, 1, 0, 255, 'The trolls answered by night. A group of them crept into Grelin''s camp, stole his journal and carried it off to their cave, the one who had it a big brute with odd markings on his skin and face. Without those notes there could be no report.', 'quest 182 reward text; quest 218 description'),
(130, 2, 0, 255, 'Once the journal was won back from Grik''nir the Cold, Grelin declared the valley''s trolls under control and finished his report. Trusting it to no apprentice, he sent it in reliable hands through the trogg-infested tunnel, past Mountaineer Thalos, to his brother Senir in Kharanos.', 'quest 218 reward text; quests 282, 420 (descriptions)'),
(130, 3, 0, 255, 'Senir read it and laughed. He had warned his brother to be sparing with the King''s name, and the report leaned on it heavily, sure to ruffle feathers in the Senate. Behind on his own work, Senir first needed Frostmane Hold scouted, the troll stronghold southwest of Brewnall Village that he had found but not dared to enter.', 'quest 420 reward text; quest 287 description'),
(130, 4, 0, 255, 'With the Hold scouted, Senir finished his report and sent it to Senator Barin Redstone in Ironforge, asking that no one mention how much help he had. Redstone read it and exploded. Authority of the King! Had Magni taken leave of his senses, and had Whitebeard taken matters into his own hands? The Senate, he warned, would not be pleased, not one bit.', 'quest 287 reward text; quest 291 description and reward text'),
(131, 1, 0, 255, 'Driving the troggs back in Coldridge Valley brings Balir little comfort. If the troubles there are any sign of what is happening elsewhere in the dwarven lands, he says, there are hard times ahead, and he can only hope that the king and the Senate are taking steps against the threat.', 'quest 170 reward text'),
(131, 2, 0, 255, 'At Gol''Bolar the troggs are thinned at last. It is a start, Stonehallow allows, and only the first of many steps that must be taken against this menace. Next he hopes to move mountaineers in to secure the quarry, then restore the works and get the miners digging again.', 'quest 433 completion and reward text'),
(132, 1, 0, 255, 'The switch is made. A barrel of Barleybrew Scalder now sits among the Thunderbrew barrels in the distillery cellar, dated to be tapped soon, and a barrel of Thunder Ale goes back to Brewnall Village as proof of the deed. Marleth is well pleased, and reminds anyone in need of a stout with a kick not to forget the Barleybrews.', 'quest 310 request and reward text; quest 311 description and reward text'),
(132, 2, 0, 255, 'The shimmerweed worked. Rejold threw it into a batch he had nearly ready, and the result was his new Shimmer Stout. A barrel went to his brother Wellart, a mountaineer at the South Gate tower who is no brewer but loves his drink. One taste put a shine in Wellart''s eyes, and he swore he could see in the dark.', 'quest 315 request and reward text; quest 415 reward text; quest 413 description and reward text'),
(132, 3, 0, 255, 'Wellart liked it so well that he kept drinking, and soon sent a cask on to a fellow mountaineer, Kadrell, who patrols the road through Thelsamar in Loch Modan. Kadrell tasted it and swore by Magni''s beard: the stout set his head turning and lightened his limbs, until he felt he could fly.', 'quest 414 description and reward text'),
(133, 1, 0, 255, 'Hildelve is found frozen in the snow, mauled and picked clean by scavengers, his journal clutched in his hand. In it he tells of being attacked by Mangeclaw, a huge ice claw bear. He drove the beast off, but it must have come back to finish him, and his last written wish was plain: revenge on Mangeclaw.', 'quest 419 reward text; quest 417 description'),
(133, 2, 0, 255, 'When Mangeclaw falls, the news brings Hammerfoot only grim comfort. Hildelve was a good friend, and he wishes he could have been there when the beast was found. The deed, he promises, will be remembered by the pilots of the Ironforge Siege Brigade.', 'quest 417 reward text'),
(134, 1, 0, 255, 'Ozzie is sure of his new formula. If it works, he declares, the captured leper will be cured and he himself will have a full head of hair again. It does not work. The sample proves too small and too impure, the troggs not irradiated enough, so Ozzie demands fallout taken straight from the slimes, lurkers and horrors deep within Gnomeregan itself.', 'quest 2926 reward text; quest 2962 description; quest 2962 description');
